; clear: VRAM all 0, from $0000; uses A, B, C
clear:  xor a
        out (VDP_CTRL),a
        ld a,$40
        out (VDP_CTRL),a        ; write from $0000
        ld bc,$4000
clr:    xor a
        out (VDP_DATA),a
        dec bc
        ld a,b
        or c
        jr nz,clr
        ret

        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
